window.SB.FIRESTORE_RULES = "rules_version = '2';\n\n// Security rules for Storyboard Maker client review links.\n// Paste this whole file into Firebase console → Firestore Database → Rules → Publish.\n//\n// Who can do what:\n// - Anyone with a review link can view the storyboard and all comments (no account needed;\n//   browsers sign in anonymously behind the scenes so people can edit their own comments).\n// - Nobody can list or browse reviews; you need the exact link.\n// - Commenters can edit or delete only their own comments. Whoever started a thread can delete it.\n// - Only the storyboard's owner (the app that holds the secret owner key) can update the\n//   storyboard, resolve comments, post \"Team\" replies, or delete anything.\n\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n    function signedIn() {\n      return request.auth != null;\n    }\n\n    function reviewPath(reviewId) {\n      return /databases/$(database)/documents/reviews/$(reviewId);\n    }\n\n    function isOwner(reviewId) {\n      return signedIn()\n        && exists(/databases/$(database)/documents/reviews/$(reviewId)/owners/$(request.auth.uid));\n    }\n\n    match /reviews/{reviewId} {\n      allow get: if true;\n      allow list: if false;\n      allow create: if signedIn()\n        && request.resource.data.ownerKeyHash is string\n        && request.resource.data.ownerKeyHash.size() == 64;\n      allow update: if isOwner(reviewId)\n        && request.resource.data.ownerKeyHash == resource.data.ownerKeyHash;\n      allow delete: if isOwner(reviewId);\n\n      // Proof of ownership: a browser becomes an owner by presenting the secret key whose\n      // SHA-256 hash is stored on the review. These documents are never readable by others.\n      match /owners/{uid} {\n        allow get: if signedIn() && request.auth.uid == uid;\n        allow create: if signedIn()\n          && request.auth.uid == uid\n          && request.resource.data.keys().hasOnly(['key', 'createdAt'])\n          && request.resource.data.key is string\n          && hashing.sha256(request.resource.data.key).toHexString().lower()\n             == get(reviewPath(reviewId)).data.ownerKeyHash;\n        allow delete: if signedIn() && request.auth.uid == uid;\n        allow list, update: if false;\n      }\n\n      match /images/{imageId} {\n        allow read: if true;\n        allow write: if isOwner(reviewId);\n      }\n\n      match /comments/{commentId} {\n        function validContent(d) {\n          return d.authorName is string\n            && d.authorName.size() > 0\n            && d.authorName.size() <= 80\n            && d.body is string\n            && d.body.size() <= 5000\n            && d.kind in ['comment', 'suggestion', 'reply'];\n        }\n\n        function startedThread() {\n          return resource.data.parentId is string\n            && get(/databases/$(database)/documents/reviews/$(reviewId)/comments/$(resource.data.parentId)).data.authorUid == request.auth.uid;\n        }\n\n        allow read: if true;\n\n        allow create: if signedIn()\n          && exists(reviewPath(reviewId))\n          && request.resource.data.authorUid == request.auth.uid\n          && validContent(request.resource.data)\n          && request.resource.data.status == 'open'\n          && request.resource.data.isTeam is bool\n          && (request.resource.data.isTeam == false || isOwner(reviewId));\n\n        allow update: if signedIn() && (\n          (resource.data.authorUid == request.auth.uid\n            && request.resource.data.diff(resource.data).affectedKeys()\n                 .hasOnly(['body', 'suggestion', 'updatedAt', 'edited', 'authorName'])\n            && validContent(request.resource.data))\n          || (isOwner(reviewId)\n            && request.resource.data.diff(resource.data).affectedKeys()\n                 .hasOnly(['status', 'resolvedAt', 'resolvedBy']))\n        );\n\n        allow delete: if signedIn() && (\n          resource.data.authorUid == request.auth.uid\n          || isOwner(reviewId)\n          || startedThread()\n        );\n      }\n    }\n  }\n}\n";
